          solution: "function partition(a, low, high) {\n  const pivot = a[high];\n  let i = low;\n  for (let j = low; j < high; j++) {\n    if (a[j] < pivot) {\n      const temp = a[i];\n      a[i] = a[j];\n      a[j] = temp;\n      i++;\n    }\n  }\n  const temp = a[i];\n  a[i] = a[high];\n  a[high] = temp;\n  return i;\n}\n\nfunction sortRange(a, low, high) {\n  if (low >= high) return;\n  const p = partition(a, low, high);\n  sortRange(a, low, p - 1);\n  sortRange(a, p + 1, high);\n}\n\nfunction quickSort(items) {\n  const a = [...items];\n  sortRange(a, 0, a.length - 1);\n  return a;\n}",
